// A localhost n8n cannot receive Telegram's push webhook, so we poll getUpdates and keep the
// offset in workflow static data. deleteWebhook first, or getUpdates 409s forever.
// Exactly ONE active workflow may poll a given bot token — two means double replies.
// $env is blocked in Code nodes on a default install (the deploy compose turns it on with
// N8N_BLOCK_ENV_ACCESS_IN_NODE=false). Read it defensively: no token simply means this
// adapter has nothing to poll, not a workflow that throws every 10 seconds.
let token = '';
try { token = $env.TELEGRAM_BOT_TOKEN || ''; } catch (e) { token = ''; }
if (!token) return [];
const store = $getWorkflowStaticData('global');
try { await this.helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${token}/deleteWebhook`, json: true }); } catch (e) {}
let res;
try {
  res = await this.helpers.httpRequest({ method: 'GET', json: true,
    url: `https://api.telegram.org/bot${token}/getUpdates`,
    qs: { offset: store.offset || 0, timeout: 0, limit: 10, allowed_updates: JSON.stringify(['message']) } });
} catch (e) { return []; }
const out = [];
for (const u of (res && res.result) || []) {
  store.offset = u.update_id + 1;                 // advance even for updates we skip
  const msg = u.message;
  if (!msg || !msg.chat) continue;
  const text = msg.text || '';
  out.push({ json: {
    user_key: `telegram:${msg.chat.id}`,
    chat_id: msg.chat.id,
    channel: 'telegram',
    name: [msg.from && msg.from.first_name, msg.from && msg.from.last_name].filter(Boolean).join(' '),
    // A sticker, photo or voice note has no text — say so rather than embedding undefined.
    text: text || '(the customer sent something that is not text)',
  } });
}
// Static data is only written back when the execution ENDS, so a run that overlaps this one
// would re-read the same updates and reply twice. Confirm them with Telegram right now: a
// getUpdates at a higher offset IS Telegram's acknowledgement, and makes re-delivery
// impossible regardless of what n8n does with the static store. An update that arrives in
// between comes back here, is ignored, and is picked up by the next tick — never lost.
if ((res && res.result || []).length) {
  try {
    await this.helpers.httpRequest({ method: 'GET', json: true,
      url: `https://api.telegram.org/bot${token}/getUpdates`,
      qs: { offset: store.offset, timeout: 0, limit: 1 } });
  } catch (e) {}
}
return out;
